<?php

namespace Database\Factories;

use App\Models\Driver;
use App\Models\MainService;
use App\Models\Project;
use App\Models\PurchaseOrderService;
use App\Models\Trip;
use App\Models\Vehicle;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * @extends Factory<Trip>
 *
 * Builds a trip row DIRECTLY — no transition, no quota charge, no history.
 * For tests that need trips to exist (the quota ledger's own tests, lists,
 * reports); tests of the trip's behaviour go through the actions in
 * App\Domain\Trips\Actions. The number (ALN-T0001) is generated by the model
 * as usual.
 */
class TripFactory extends Factory
{
    public function definition(): array
    {
        return [
            'project_id' => Project::factory(),
            'company_id' => fn (array $attributes) => Project::find($attributes['project_id'])->company_id,
            'trip_at' => now(),
            'status' => Trip::STATUS_AWAITING_CLIENT_APPROVAL,
            'source' => Trip::SOURCE_STAFF,
            'requires_client_approval' => true,
            'requires_purchase_order' => false,
            'driver_id' => Driver::factory(),
            'vehicle_id' => Vehicle::factory(),
            'main_service_id' => MainService::factory(),
            'trip_cost' => 50,
            'ancillary_cost' => 0,
        ];
    }

    public function forProject(Project $project): static
    {
        return $this->state(['project_id' => $project->id, 'company_id' => $project->company_id]);
    }

    /** A trip of the line's project and service, linked to the line with its costs (not charged — no ledger row). */
    public function onLine(PurchaseOrderService $line): static
    {
        $line->loadMissing('purchaseOrder');

        return $this->state([
            'project_id' => $line->purchaseOrder->project_id,
            'company_id' => $line->purchaseOrder->company_id,
            'main_service_id' => $line->main_service_id,
            'requires_purchase_order' => true,
            'purchase_order_service_id' => $line->id,
            'trip_cost' => $line->trip_cost,
            'ancillary_cost' => $line->tracksAncillary() ? $line->ancillary_cost_per_trip : 0,
        ]);
    }

    public function status(string $status): static
    {
        return $this->state(['status' => $status]);
    }
}
